import pytest
from unittest.mock import Mock, patch, MagicMock
from chipsec.hal.common.acpi import ACPI, ACPI_TABLE_HEADER
from chipsec.library.acpi_tables import DMAR, APIC, XSDT, UEFI_TABLE, WSMT
from tests.test_utils import MockFactory, TestDataGenerator


class TestACPI:
    """Comprehensive tests for ACPI HAL functionality."""

    @pytest.fixture
    def mock_cs(self):
        """Create mock ChipsecCs object."""
        return MockFactory.create_mock_chipsec_cs()

    @pytest.fixture
    def acpi_instance(self, mock_cs):
        """Create ACPI instance with mocked dependencies."""
        with patch('chipsec.hal.common.acpi.acpi_tables'):
            return ACPI(mock_cs)

    @pytest.mark.unit
    def test_acpi_initialization(self, acpi_instance):
        """Test ACPI class initialization."""
        assert hasattr(acpi_instance, 'cs')
        assert hasattr(acpi_instance, 'logger')

    @pytest.mark.unit
    def test_read_rsdp_invalid(self, acpi_instance, mock_cs):
        """Test reading invalid RSDP returns None."""
        with patch.object(acpi_instance, '_find_RSDP_in_EFI_config_table',
                         return_value=(None, None)):
            result = acpi_instance.read_RSDP(0x1000)
            assert result is None
            # The result should be None when RSDP signature is invalid

    @pytest.mark.unit
    def test_read_rsdp_not_found(self, acpi_instance, mock_cs):
        """Test RSDP not found scenario."""
        with patch.object(acpi_instance, '_find_RSDP_in_EFI_config_table',
                         return_value=(None, None)):
            with patch.object(acpi_instance, '_find_RSDP_in_legacy_BIOS_segments',
                             return_value=(None, None)):
                with patch.object(acpi_instance, '_find_RSDP_in_EFI',
                                 return_value=(None, None)):
                    result = acpi_instance.read_RSDP(0x1000)
                    assert result is None

    @pytest.mark.unit
    def test_find_rsdp_success(self, acpi_instance, mock_cs):
        """Test successful RSDP finding."""
        mock_rsdp = Mock()
        mock_rsdp.Revision = 2

        with patch.object(acpi_instance, '_find_RSDP_in_EFI_config_table',
                         return_value=(mock_rsdp, 0x1000)):
            pa, rsdp = acpi_instance.find_RSDP()
            assert pa == 0x1000
            assert rsdp == mock_rsdp

    @pytest.mark.unit
    def test_get_sdt_xsdt_success(self, acpi_instance, mock_cs):
        """Test getting SDT with XSDT."""
        mock_rsdp = Mock()
        mock_rsdp.Revision = 2
        mock_rsdp.XsdtAddress = 0x2000

        mock_xsdt = Mock()
        mock_xsdt.Length = 100
        mock_xsdt.Signature = b'XSDT'

